mapper.select:
SELECT ui.uid, ui.username, IFNULL(col.name, '-') AS college, IFNULL(cls.name, '-') AS majorClass, ui.email, ui.phone FROM user_info ui INNER JOIN ( SELECT ur.user_uid FROM user_role ur WHERE ur.role_id IN
#{rid}
GROUP BY ur.user_uid ) urp ON urp.user_uid = ui.uid LEFT JOIN sys_college col ON col.id = ui.college_id LEFT JOIN sys_class cls ON cls.id = ui.class_id ORDER BY ui.gmt_create DESC

SELECT ui.uid, ui.username, ui.realname, ui.avatar, ui.college_id AS collegeId, IFNULL(col.name, '-') AS college, ui.grade, ui.class_id AS classId, IFNULL(cls.name, '-') AS majorClass, ui.status FROM user_info ui LEFT JOIN sys_college col ON col.id = ui.college_id LEFT JOIN sys_class cls ON cls.id = ui.class_id
AND ( ui.uid LIKE CONCAT('%', #{keyword}, '%') OR ui.username LIKE CONCAT('%', #{keyword}, '%') OR ui.realname LIKE CONCAT('%', #{keyword}, '%') )
AND ui.college_id = #{collegeId}
AND ui.grade = #{grade}
AND ui.class_id = #{classId}
ORDER BY ui.gmt_create DESC
